Here is the commit message:
wifi: mac80211_hwsim: fix typo in frequency notification

The NAN notification is for 5745 MHz which corresponds to channel 149
and not 5475 which is not actually a valid channel. This could result in
a NULL pointer dereference in cfg80211_next_nan_dw_notif.

Fixes: a37a6f54439b ("wifi: mac80211_hwsim: Add simulation support for NAN device")
Signed-off-by: Benjamin Berg <benjamin.berg@intel.com>
Reviewed-by: Ilan Peer <ilan.peer@intel.com>
Reviewed-by: Miriam Rachel Korenblit <miriam.rachel.korenblit@intel.com>
Link: https://patch.msgid.link/20260107143652.7dab2035836f.Iacbaf7bb94ed5c14a0928a625827e4137d8bfede@changeid
Signed-off-by: Johannes Berg <johannes.berg@intel.com>

Here is the root cause:
The bug is caused by a typo in the frequency value used for the NAN dwell notification in the mac80211_hwsim driver. The code used 5475 MHz, which is not a valid channel frequency in the 5 GHz band, instead of the correct 5745 MHz (channel 149). This results in `ieee80211_get_channel` returning NULL, which then leads to a NULL pointer dereference in `cfg80211_next_nan_dw_notif` when the NULL channel pointer is dereferenced.

Here is the patch:

 static enum hrtimer_restart
 mac80211_hwsim_nan_dw_start(struct hrtimer *timer)
 {
 	struct mac80211_hwsim_data *data =
 		container_of(timer, struct mac80211_hwsim_data,
 			     nan_timer);
 	struct ieee80211_hw *hw = data->hw;
 	u64 orig_tsf = mac80211_hwsim_get_tsf(hw, NULL), tsf = orig_tsf;
 	u32 dw_int = 512 * 1024;
 	u64 until_dw;

 	if (!data->nan_device_vif)
 		return HRTIMER_NORESTART;

 	if (data->nan_bands & BIT(NL80211_BAND_5GHZ)) {
 		if (data->nan_curr_dw_band == NL80211_BAND_2GHZ) {
 			dw_int = 128 * 1024;
 			data->nan_curr_dw_band = NL80211_BAND_5GHZ;
 		} else if (data->nan_curr_dw_band == NL80211_BAND_5GHZ) {
 			data->nan_curr_dw_band = NL80211_BAND_2GHZ;
 		}
 	}

 	until_dw = dw_int - do_div(tsf, dw_int);

 	/* The timer might fire just before the actual DW, in which case
 	 * update the timeout to the actual next DW
 	 */
 	if (until_dw < dw_int / 2)
 		until_dw += dw_int;

 	/* The above do_div() call directly modifies the 'tsf' variable, thus,
 	 * use a copy so that the print below would show the original TSF.
 	 */
 	wiphy_debug(hw->wiphy,
 		    "%s: tsf=%llx, curr_dw_band=%u, next_dw=%llu\n",
 		    __func__, orig_tsf, data->nan_curr_dw_band,
 		    until_dw);

 	hrtimer_forward_now(&data->nan_timer,
 			    ns_to_ktime(until_dw * NSEC_PER_USEC));

 	if (data->notify_dw) {
 		struct ieee80211_channel *ch;
 		struct wireless_dev *wdev =
 			ieee80211_vif_to_wdev(data->nan_device_vif);

 		if (data->nan_curr_dw_band == NL80211_BAND_5GHZ)
-			ch = ieee80211_get_channel(hw->wiphy, 5475);
+			ch = ieee80211_get_channel(hw->wiphy, 5745);
 		else
 			ch = ieee80211_get_channel(hw->wiphy, 2437);

 		cfg80211_next_nan_dw_notif(wdev, ch, GFP_ATOMIC);
 	}

 	return HRTIMER_RESTART;
 }



